interface PostRepository {
    fun observeFeed(): Flow<List<Post>>
    suspend fun refreshFeed(force: Boolean = false): RefreshResult
}

class OfflinePostRepository(
    private val api: PostApi,
    private val dao: PostDao,
    private val clock: Clock
) : PostRepository {
    override fun observeFeed(): Flow<List<Post>> =
        dao.observeAll().map { rows -> rows.map(PostEntity::toDomain) }

    override suspend fun refreshFeed(force: Boolean): RefreshResult {
        if (!force && dao.isFresh(clock.now())) return RefreshResult.SkippedFresh
        val dto = api.getFeed()
        dao.replaceAllInTransaction(dto.map(PostDto::toEntity), clock.now())
        return RefreshResult.Updated(dto.size)
    }
}

class FeedRepositoryImpl(
    private val remote: FeedRemoteDataSource,
    private val local: FeedLocalDataSource
) : FeedRepository {
    private val refreshMutex = Mutex()

    override suspend fun refresh(): RefreshResult = refreshMutex.withLock {
        val snapshot = remote.fetchFeed()
        local.replaceSnapshot(snapshot.map(FeedDto::toEntity))
        RefreshResult.Success
    }
}

@Transaction
suspend fun enqueueMessage(draft: MessageDraft) {
    val local = draft.toPendingEntity()
    messageDao.insert(local)
    outboxDao.insert(OutboxEntity.sendMessage(local.clientId, local.payload))
}
// Worker đọc outbox, gửi idempotency key, rồi cập nhật message + xoá outbox trong transaction.
